import { type Anchor, anchorText } from "./selection.ts";
import type { Message } from "./thread.ts";

export type Action =
  | { type: "explain" }
  | { type: "quiz" }
  | { type: "query"; text: string };

/** Learning mode: the agent is explaining work that already happened, to a
 * user who chose the passage they are stuck on. */
export const LEARNING_SYSTEM = [
  "You are helping a user understand engineering work that was done for them.",
  "They will show you a transcript and point at a passage they picked out.",
  "Answer about that passage specifically, in plain language, and assume the",
  "user has not followed the reasoning that produced it. Be concise, and do",
  "not restate the whole transcript back to them.",
  "",
  "You may be shown a knowledge graph: what we believe this user already",
  "understands, one line per node and edge, each with an id and a level on the",
  "scale 1 unfamiliar, 2 emerging, 3 working, 4 fluent. Pitch your answer to",
  "it: build on what they are fluent in and slow down on what they are not.",
  "The overview is titles only, so call the `get` tool with the ids of",
  "anything you are about to lean on to read its full description and the",
  "notes on this user. You cannot change the graph; do not offer to.",
].join(" ");

/** The single synthetic user turn seeding a learning thread. `seed` is the
 * parent's own seed and is emitted verbatim - wrapping or re-labelling it
 * would nest the framing one layer deeper at every level. */
export function seedTurn(
  seed: string | undefined,
  messages: ReadonlyArray<Message>,
  anchor: Anchor,
  action: Action,
  graph?: string,
): string {
  const visible = messages.slice(0, anchor.end.msg + 1);
  const sections = [];
  // Only the topmost learning thread renders the graph: a deeper thread's
  // `seed` is its parent's, which already carries it, and repeating it would
  // show the model the same overview once per level.
  if (seed) sections.push(seed);
  else if (graph)
    sections.push(`What this user already understands:\n${graph}`);
  sections.push(transcript(visible));
  sections.push(
    `The user then selected: "${anchorText(anchor, visible)}"\n${question(action)}`,
  );
  return sections.join("\n\n");
}

function transcript(messages: ReadonlyArray<Message>): string {
  return messages
    .map((m) => `${m.role === "user" ? "User" : "Assistant"}: ${line(m)}`)
    .join("\n\n");
}

function line(message: Message): string {
  return message.type === "text"
    ? message.text
    : `[called tool ${message.call.name} with ${message.call.inputJson}]`;
}

/** How the thread was opened, shown at the top of its pane so the user can see
 * what they asked for. */
export function actionLabel(action: Action): string {
  switch (action.type) {
    case "explain":
      return "I don't understand this.";
    case "quiz":
      return "Quiz me on this.";
    case "query":
      return action.text;
  }
}

function question(action: Action): string {
  switch (action.type) {
    case "explain":
      return "They said they don't understand this. Explain what it means and why it is there.";
    case "quiz":
      return "They asked to be quizzed on this. Ask one question that checks whether they understand it, and wait for their answer.";
    case "query":
      return `They asked: ${action.text}`;
  }
}

import {
  type GraphEdge,
  type GraphNode,
  KnowledgeGraph,
  type NodeId,
} from "../graph.ts";
import { readTools } from "../graph-tools.ts";
import type { Msg as GraphMsg, Sidebar } from "../graph-view.ts";
import { layout, type Position } from "../layout.ts";
import { actionLabel } from "../prompt.ts";
import { selectedSample, selectSample } from "../samples/index.ts";
import { anchorText, overlaps, type ThreadId } from "../selection.ts";
import { Thread } from "../thread.ts";
import { ThreadTree } from "../threads.ts";
import { AppView, type Msg, type State } from "../view.ts";

/** The editable fields of a node or edge: the id addresses it, so it is not
 * part of what the sidebar edits. */
function draftOf(node: GraphNode): Omit<GraphNode, "id">;
function draftOf(edge: GraphEdge): Omit<GraphEdge, "id">;
function draftOf<T extends { id: string }>(item: T): Omit<T, "id"> {
  const { id: _id, ...rest } = item;
  return rest;
}

function connect(): WebSocket {
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  return new WebSocket(`${proto}//${window.location.host}/api/socket`);
}

/** Prototype 1: the task transcript, with learning threads hanging off the
 * passages the user picks out of it. */
export function mount(container: HTMLElement): void {
  // One socket for the whole app: every Thread adds its own
  // listener and drops frames whose requestId it does not own, so streams
  // interleave over the single connection.
  const socket = connect();
  // Scoped to the user, not to a thread: it outlives every thread in the tree
  // and is discarded only by a page load.
  const graph = new KnowledgeGraph();
  const tree = new ThreadTree(
    socket,
    new Thread(socket, { initialTurns: selectedSample()?.turns }),
    () => {
      refresh();
      view.sync(state);
    },
  );
  // The thread on the left. Moved only by the arrows.
  let focus = tree.root;
  let sidebar: Sidebar = { type: "closed" };
  // The layout is a few hundred iterations, and refresh() runs on every
  // keystroke, so it is recomputed only when the shape of the graph changes.
  let placement = new Map<NodeId, Position>();
  let placedFor = "";
  // Purely presentational, and per thread: which messages the user has
  // expanded past the collapsed height.
  const expanded = new Map<ThreadId, Set<number>>();
  function expandedFor(id: ThreadId): Set<number> {
    let set = expanded.get(id);
    if (!set) {
      set = new Set();
      expanded.set(id, set);
    }
    return set;
  }

  const state: State = {
    sample: selectedSample()?.id ?? "",
    messages: [],
    inFlight: false,
    draft: "",
    split: false,
    depth: 0,
    canDescend: false,
    thread: focus,
    marks: [],
    activeMark: null,
    anchor: null,
    tab: "threads",
    graph: { nodes: [], edges: [], sidebar },
    query: "",
    origin: null,
    expanded: new Set(),
    child: null,
  };

  /** Re-projects the tree onto the view's state. Everything but the fields the
   * user is editing is derived, so this runs after every dispatch. */
  /** The graph projected onto view state: positions from `layout`, and the
   * sidebar the user is editing. */
  function refreshGraph(): void {
    const nodes = graph.nodes;
    const edges = graph.edges;
    const shape = [
      ...nodes.map((n) => n.id),
      ...edges.map((e) => `${e.id}:${e.from}->${e.to}`),
    ].join(",");
    if (shape !== placedFor) {
      placement = layout(graph);
      placedFor = shape;
    }
    const at = (id: NodeId): Position =>
      placement.get(id) ?? { x: 0.5, y: 0.5 };
    state.graph = {
      nodes: nodes.map((n) => ({ ...n, pos: at(n.id) })),
      edges: edges.map((e) => ({ ...e, from_: at(e.from), to_: at(e.to) })),
      sidebar,
    };
  }

  function refresh(): void {
    refreshGraph();
    const node = tree.get(focus);
    state.thread = focus;
    state.depth = state.split ? tree.path(focus).length : 0;
    state.canDescend = node.activeChild !== null;
    state.messages = node.thread.messages;
    state.inFlight = node.thread.inFlight;
    state.draft = node.draft;
    state.marks = tree.marks(focus);
    state.expanded = expandedFor(focus);
    const own = node.origin;
    state.origin = own
      ? {
          action: actionLabel(own.action),
          quote: anchorText(
            own.anchor,
            tree.get(own.anchor.thread).thread.messages,
          ),
        }
      : null;
    state.activeMark = node.activeChild;
    const activeChild = node.activeChild;
    if (!activeChild) {
      state.child = null;
      return;
    }
    const child = tree.get(activeChild);
    const origin = child.origin;
    state.child = {
      action: origin ? actionLabel(origin.action) : "",
      messages: child.thread.messages,
      inFlight: child.thread.inFlight,
      draft: child.draft,
      expanded: expandedFor(activeChild),
    };
  }

  function send(id: ThreadId): void {
    const node = tree.get(id);
    const text = node.draft.trim();
    if (text === "" || node.thread.inFlight) return;
    node.draft = "";
    node.thread.send(text).then(undefined, (e: unknown) => {
      console.error(e);
    });
  }

  /** The graph tab's own reducer. It writes to the graph and to `sidebar`;
   * everything the canvas shows is re-derived in refreshGraph(). */
  function updateGraph(msg: GraphMsg): void {
    switch (msg.type) {
      case "SELECT_NODE": {
        const node = graph.node(msg.id);
        if (!node) break;
        sidebar = {
          type: "node",
          id: node.id,
          draft: draftOf(node),
          error: null,
        };
        break;
      }
      case "SELECT_EDGE": {
        const edge = graph.edge(msg.id);
        if (!edge) break;
        sidebar = {
          type: "edge",
          id: edge.id,
          draft: draftOf(edge),
          error: null,
        };
        break;
      }
      case "CLOSE":
        sidebar = { type: "closed" };
        break;
      case "NODE_FIELD":
        if (sidebar.type === "node") sidebar.draft[msg.field] = msg.value;
        break;
      case "LEVEL_CHANGED":
        if (sidebar.type === "node") sidebar.draft.level = msg.level;
        break;
      case "EDGE_FIELD":
        if (sidebar.type === "edge") sidebar.draft[msg.field] = msg.value;
        break;
      case "SAVE": {
        if (sidebar.type === "closed") break;
        const result =
          sidebar.type === "node"
            ? graph.putNode({ id: sidebar.id, ...sidebar.draft })
            : graph.putEdge({ id: sidebar.id, ...sidebar.draft });
        // A rejected save keeps the draft, so the user's typing survives.
        sidebar.error = result.status === "error" ? result.error : null;
        break;
      }
      case "DELETE": {
        if (sidebar.type === "closed") break;
        if (sidebar.type === "node") graph.deleteNode(sidebar.id);
        else graph.deleteEdge(sidebar.id);
        sidebar = { type: "closed" };
        break;
      }
    }
  }

  function update(state: State, msg: Msg): void {
    const node = tree.get(focus);
    switch (msg.type) {
      case "DRAFT_CHANGED":
        node.draft = msg.draft;
        break;
      case "SAMPLE_CHANGED":
        selectSample(msg.id === "" ? undefined : msg.id);
        break;
      case "TAB_CHANGED":
        state.tab = msg.tab;
        break;
      case "GRAPH_MSG":
        updateGraph(msg.msg);
        break;
      case "SUBMIT":
        send(focus);
        break;
      case "GO_DEEPER": {
        if (!state.split) {
          state.split = true;
          break;
        }
        const child = node.activeChild;
        if (!child) break;
        focus = child;
        state.anchor = null;
        state.query = "";
        break;
      }
      case "GO_BACK": {
        const parent = node.origin?.anchor.thread;
        if (parent === undefined) state.split = false;
        else focus = parent;
        state.anchor = null;
        state.query = "";
        break;
      }
      case "TOGGLE_EXPANDED": {
        const set = expandedFor(focus);
        if (!set.delete(msg.index)) set.add(msg.index);
        break;
      }
      case "SELECTION_CHANGED":
        state.anchor = msg.anchor;
        node.activeChild = null;
        break;
      case "MARK_CLICKED":
        state.anchor = null;
        node.activeChild = msg.thread;
        break;
      case "LEARNING_MSG":
        switch (msg.msg.type) {
          case "ACTION": {
            const anchor = state.anchor;
            if (!anchor || overlaps(state.marks, anchor)) break;
            const id = tree.open(anchor, msg.msg.action, {
              tools: readTools(graph),
              graph: graph.render(),
            });
            state.anchor = null;
            state.query = "";
            tree
              .get(id)
              .thread.start()
              .then(undefined, (e: unknown) => {
                console.error(e);
              });
            break;
          }
          case "QUERY_CHANGED":
            state.query = msg.msg.query;
            break;
        }
        break;
      case "CHILD_MSG": {
        const activeChild = node.activeChild;
        if (!activeChild) break;
        switch (msg.msg.type) {
          case "DRAFT_CHANGED":
            tree.get(activeChild).draft = msg.msg.draft;
            break;
          case "SUBMIT":
            send(activeChild);
            break;
          case "TOGGLE_EXPANDED": {
            const set = expandedFor(activeChild);
            if (!set.delete(msg.msg.index)) set.add(msg.msg.index);
            break;
          }
        }
        break;
      }
    }
    refresh();
  }

  let dispatching = false;
  function dispatch(msg: Msg): void {
    if (dispatching) throw new Error("dispatch-in-dispatch");
    dispatching = true;
    update(state, msg);
    view.sync(state);
    dispatching = false;
  }

  // The graph has no writer until the extraction thread of the next stage, so
  // e2e specs seed it through this handle.
  (window as unknown as { __graph?: KnowledgeGraph }).__graph = graph;

  refresh();
  const view = new AppView(container, dispatch, state);
}

import type Anthropic from "@anthropic-ai/sdk";
import { type Action, LEARNING_SYSTEM, seedTurn } from "./prompt.ts";
import type { Anchor, Mark, ThreadId } from "./selection.ts";
import type { Tool, ToolName, TurnResult } from "./thread.ts";
import { type Socket, Thread } from "./thread.ts";

export type { Action };

/** `anchor.thread` is the parent, so the link upward is the highlight itself. */
export type Origin = { anchor: Anchor; action: Action };

/** What a child thread is given beyond its seed. */
export type ChildOpts = {
  tools?: Record<ToolName, Tool>;
  /** The rendered knowledge graph, injected into the seed of a top-level
   * learning thread. */
  graph?: string;
  yieldSchema?: Anthropic.Tool.InputSchema | "text";
};

export type TreeNode = {
  id: ThreadId;
  /** null only for the root task thread. */
  origin: Origin | null;
  thread: Thread;
  /** Creation order; each child's `origin.anchor` is its highlight. */
  children: ThreadId[];
  activeChild: ThreadId | null;
  draft: string;
};

/** The tree of threads. Every thread but the root was opened from a
 * passage of its parent, so a thread and the highlight over its parent are the
 * same edge seen from either end. Threads are never destroyed or reparented. */
export class ThreadTree {
  private readonly threads = new Map<ThreadId, TreeNode>();
  private nextId = 0;
  readonly root: ThreadId;
  private readonly socket: Socket;
  /** Attached to every thread the tree owns, so a stream anywhere in the
   * tree re-syncs the app. */
  private readonly onChange: () => void;

  constructor(socket: Socket, root: Thread, onChange: () => void) {
    this.socket = socket;
    this.onChange = onChange;
    this.root = this.add(null, root);
  }

  get(id: ThreadId): TreeNode {
    const node = this.threads.get(id);
    if (!node) throw new Error(`unknown thread ${id}`);
    return node;
  }

  /** Seeds a child thread from the parent's own seed plus its transcript
   * up to `anchor`, links it in, and makes it the parent's active child. The
   * caller starts it: the tree does not own the request lifecycle. */
  open(anchor: Anchor, action: Action, opts: ChildOpts = {}): ThreadId {
    const parent = this.get(anchor.thread);
    const thread = new Thread(this.socket, {
      system: LEARNING_SYSTEM,
      seed: seedTurn(
        parent.thread.seed,
        parent.thread.messages,
        anchor,
        action,
        opts.graph,
      ),
      tools: opts.tools,
      yieldSchema: opts.yieldSchema,
    });
    const id = this.add({ anchor, action }, thread);
    parent.children.push(id);
    parent.activeChild = id;
    return id;
  }

  /** What a child thread settled with, once it has yielded. The parent renders
   * threads it never awaited, so the settled value has to be readable here. */
  result(id: ThreadId): TurnResult | undefined {
    return this.get(id).thread.result;
  }

  /** The highlights to draw over `id`'s transcript: one per child. */
  marks(id: ThreadId): Mark[] {
    return this.get(id).children.map((child) => {
      const origin = this.get(child).origin;
      if (!origin) throw new Error("child thread without an origin");
      return { thread: child, anchor: origin.anchor };
    });
  }

  /** root -> id, for the depth indicator. */
  path(id: ThreadId): ThreadId[] {
    const out: ThreadId[] = [];
    let at: ThreadId | undefined = id;
    while (at) {
      out.unshift(at);
      at = this.get(at).origin?.anchor.thread;
    }
    return out;
  }

  private add(origin: Origin | null, thread: Thread): ThreadId {
    const id = `t${this.nextId++}` as ThreadId;
    thread.onChange = this.onChange;
    this.threads.set(id, {
      id,
      origin,
      thread,
      children: [],
      activeChild: null,
      draft: "",
    });
    return id;
  }
}

import type { EdgeId, GraphEdge, GraphNode, Level, NodeId } from "./graph.ts";
import { LEVELS } from "./graph.ts";
import type { Position } from "./layout.ts";
import {
  Binder,
  cls,
  mountStyle,
  ref,
  sanitize,
  showKeyed,
  type View,
} from "./vamp.ts";

/** The sidebar is a small state machine: nothing selected, or a selection
 * together with the draft being edited. There is no state in which something
 * is selected and there is no draft, so the two are one field. */
export type Sidebar =
  | { type: "closed" }
  | {
      type: "node";
      id: NodeId;
      draft: Omit<GraphNode, "id">;
      error: string | null;
    }
  | {
      type: "edge";
      id: EdgeId;
      draft: Omit<GraphEdge, "id">;
      error: string | null;
    };

export type State = {
  nodes: ReadonlyArray<GraphNode & { pos: Position }>;
  edges: ReadonlyArray<GraphEdge & { from_: Position; to_: Position }>;
  sidebar: Sidebar;
};

/** `field` is keyed off what is open, so a message for the wrong kind of
 * selection does not typecheck. */
export type Msg =
  | { type: "SELECT_NODE"; id: NodeId }
  | { type: "SELECT_EDGE"; id: EdgeId }
  | { type: "CLOSE" }
  | {
      type: "NODE_FIELD";
      field: "title" | "description" | "notes";
      value: string;
    }
  | { type: "LEVEL_CHANGED"; level: Level }
  | { type: "EDGE_FIELD"; field: "title" | "description"; value: string }
  | { type: "SAVE" }
  | { type: "DELETE" };

/** The canvas is sized in pixels rather than percentages: an edge is a rotated
 * bar, and a bar whose length is a percentage of the width but whose angle is
 * computed in square coordinates would shear on a non-square canvas. */
const WIDTH = 900;
const HEIGHT = 560;
const PAD = 60;

const px = (pos: Position) => ({
  x: PAD + pos.x * (WIDTH - 2 * PAD),
  y: PAD + pos.y * (HEIGHT - 2 * PAD),
});

const graphClass = cls("graph");
const canvasClass = cls("graph-canvas");
const nodeClass = cls("graph-node");
const edgeClass = cls("graph-edge");
const edgeBarClass = cls("graph-edge-bar");
const edgeLabelClass = cls("graph-edge-label");
const sidebarClass = cls("graph-sidebar");
const emptyClass = cls("graph-empty");
const errorClass = cls("graph-error");
const actionsClass = cls("graph-actions");

mountStyle(`
.${graphClass} {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 20rem;
  gap: 1.5rem;
  padding: 1rem;
  align-items: start;
}
.${canvasClass} {
  position: relative;
  width: ${WIDTH}px;
  height: ${HEIGHT}px;
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 0.5rem;
  background: #fcfcfc;
  overflow: hidden;
}
.${emptyClass} {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.5;
  font-style: italic;
}
.${nodeClass} {
  position: absolute;
  transform: translate(-50%, -50%);
  max-width: 9rem;
  padding: 0.3rem 0.6rem;
  border: 1px solid rgba(0, 0, 0, 0.25);
  border-radius: 999px;
  background: #fff;
  font-size: 0.8rem;
  text-align: center;
  cursor: pointer;
  z-index: 1;
}
.${nodeClass}[data-selected="true"] {
  box-shadow: 0 0 0 2px #f0b429;
}
.${nodeClass}[data-level="1"] { background: #f4f4f4; }
.${nodeClass}[data-level="2"] { background: #e8f0fb; }
.${nodeClass}[data-level="3"] { background: #d3e5fb; }
.${nodeClass}[data-level="4"] { background: #b8d8f8; }
.${edgeClass} {
  position: absolute;
}
.${edgeBarClass} {
  position: absolute;
  height: 2px;
  transform-origin: 0 50%;
  background: rgba(0, 0, 0, 0.3);
  cursor: pointer;
}
.${edgeLabelClass} {
  position: absolute;
  transform: translate(-50%, -50%);
  font-size: 0.7rem;
  padding: 0 0.2rem;
  background: #fcfcfc;
  cursor: pointer;
  white-space: nowrap;
}
.${edgeClass}[data-selected="true"] .${edgeBarClass} {
  background: #f0b429;
}
.${sidebarClass} {
  position: sticky;
  top: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  font-size: 0.9rem;
}
.${sidebarClass} input,
.${sidebarClass} textarea,
.${sidebarClass} select {
  font: inherit;
  width: 100%;
  padding: 0.3rem;
  box-sizing: border-box;
}
.${actionsClass} {
  display: flex;
  gap: 0.5rem;
}
.${actionsClass} button {
  font: inherit;
}
.${errorClass} {
  color: #b00020;
}
`);

type NodeState = { node: GraphNode; pos: Position; selected: boolean };

class NodeView implements View<NodeState, { type: "CLICKED" }> {
  container: HTMLElement;
  private b: Binder<NodeState>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: { type: "CLICKED" }) => void,
    initial: NodeState,
  ) {
    const titleRef = ref("node-title");
    container.className = nodeClass;
    container.innerHTML = sanitize`<span data-node-title data-ref="${titleRef}"></span>`;
    this.container = container;
    this.b = new Binder(container, initial);
    container.addEventListener("click", () => dispatch({ type: "CLICKED" }));
    this.b.bindContainerStyle((s) => {
      const at = px(s.pos);
      return { left: `${at.x}px`, top: `${at.y}px` };
    });
    this.b.bindContainerAttr("data-node", (s) => s.node.id);
    this.b.bindContainerAttr("data-level", (s) => String(s.node.level));
    this.b.bindContainerAttr("data-selected", (s) =>
      s.selected ? "true" : undefined,
    );
    this.b.bindText(titleRef, (s) => s.node.title);
  }

  sync(state: NodeState): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

type EdgeState = {
  edge: GraphEdge;
  from_: Position;
  to_: Position;
  selected: boolean;
};

/** A rotated div rather than SVG: bindList builds children with
 * createElement and Binder.ref is typed to HTMLElement, so an SVG layer would
 * mean imperative DOM or widening vamp. Straight lines are all we need. */
class EdgeView implements View<EdgeState, { type: "CLICKED" }> {
  container: HTMLElement;
  private b: Binder<EdgeState>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: { type: "CLICKED" }) => void,
    initial: EdgeState,
  ) {
    const barRef = ref("edge-bar");
    const labelRef = ref("edge-label");
    container.className = edgeClass;
    container.innerHTML = sanitize`
      <div class="${edgeBarClass}" data-ref="${barRef}"></div>
      <div class="${edgeLabelClass}" data-edge-label data-ref="${labelRef}"></div>
    `;
    this.container = container;
    this.b = new Binder(container, initial);
    container.addEventListener("click", () => dispatch({ type: "CLICKED" }));
    this.b.bindContainerAttr("data-edge", (s) => s.edge.id);
    this.b.bindContainerAttr("data-selected", (s) =>
      s.selected ? "true" : undefined,
    );
    this.b.bindStyle(barRef, (s) => {
      const from = px(s.from_);
      const to = px(s.to_);
      const angle = Math.atan2(to.y - from.y, to.x - from.x);
      return {
        left: `${from.x}px`,
        top: `${from.y}px`,
        width: `${Math.hypot(to.x - from.x, to.y - from.y)}px`,
        transform: `rotate(${angle}rad)`,
      };
    });
    this.b.bindStyle(labelRef, (s) => {
      const from = px(s.from_);
      const to = px(s.to_);
      return {
        left: `${(from.x + to.x) / 2}px`,
        top: `${(from.y + to.y) / 2}px`,
      };
    });
    this.b.bindText(labelRef, (s) => s.edge.title);
  }

  sync(state: EdgeState): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

export class GraphView implements View<State, Msg> {
  container: HTMLElement;
  private b: Binder<State>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initial: State,
  ) {
    const canvasRef = ref("graph-canvas");
    const edgesRef = ref("graph-edges");
    const emptyRef = ref("graph-empty");
    const sidebarRef = ref("graph-sidebar");
    const closedRef = ref("graph-closed");
    const openRef = ref("graph-open");
    const kindRef = ref("graph-kind");
    const titleRef = ref("graph-title");
    const descriptionRef = ref("graph-description");
    const notesRowRef = ref("graph-notes-row");
    const notesRef = ref("graph-notes");
    const levelRowRef = ref("graph-level-row");
    const levelRef = ref("graph-level");
    const errorRef = ref("graph-error");
    const saveRef = ref("graph-save");
    const deleteRef = ref("graph-delete");
    const closeRef = ref("graph-close");

    container.className = graphClass;
    container.innerHTML = sanitize`
      <div class="${canvasClass}" data-graph-canvas data-ref="${canvasRef}">
        <p class="${emptyClass}" data-ref="${emptyRef}">Nothing here yet.</p>
        <div data-ref="${edgesRef}"></div>
      </div>
      <div class="${sidebarClass}" data-ref="${sidebarRef}">
        <p data-ref="${closedRef}">Click a node or an edge to edit it.</p>
        <div data-ref="${openRef}">
          <strong data-graph-kind data-ref="${kindRef}"></strong>
          <label>Title<input data-graph-title data-ref="${titleRef}" /></label>
          <label>Description<textarea rows="3" data-graph-description data-ref="${descriptionRef}"></textarea></label>
          <label data-ref="${notesRowRef}">Notes<textarea rows="3" data-graph-notes data-ref="${notesRef}"></textarea></label>
          <label data-ref="${levelRowRef}">Understanding<select data-graph-level data-ref="${levelRef}"></select></label>
          <p class="${errorClass}" data-graph-error data-ref="${errorRef}"></p>
          <div class="${actionsClass}">
            <button type="button" data-ref="${saveRef}">Save</button>
            <button type="button" data-ref="${deleteRef}">Delete</button>
            <button type="button" data-ref="${closeRef}">Close</button>
          </div>
        </div>
      </div>
    `;
    this.container = container;
    this.b = new Binder(container, initial);

    this.b.bindList(canvasRef, "div", (s) =>
      s.nodes.map((node) =>
        showKeyed(
          node.id,
          NodeView,
          { node, pos: node.pos, selected: selectedId(s) === node.id },
          {},
          () => dispatch({ type: "SELECT_NODE", id: node.id }),
        ),
      ),
    );
    this.b.bindList(edgesRef, "div", (s) =>
      s.edges.map((edge) =>
        showKeyed(
          edge.id,
          EdgeView,
          {
            edge,
            from_: edge.from_,
            to_: edge.to_,
            selected: selectedId(s) === edge.id,
          },
          {},
          () => dispatch({ type: "SELECT_EDGE", id: edge.id }),
        ),
      ),
    );

    const level = this.b.ref<HTMLSelectElement>(levelRef);
    LEVELS.forEach((label, i) => {
      const option = document.createElement("option");
      option.value = String(i + 1);
      option.textContent = `${i + 1} ${label}`;
      level.append(option);
    });
    level.addEventListener("change", () =>
      dispatch({
        type: "LEVEL_CHANGED",
        level: Number(level.value) as Level,
      }),
    );

    const title = this.b.ref<HTMLInputElement>(titleRef);
    const description = this.b.ref<HTMLTextAreaElement>(descriptionRef);
    const notes = this.b.ref<HTMLTextAreaElement>(notesRef);
    let current = initial;
    const edit = (
      field: "title" | "description" | "notes",
      value: string,
    ): void => {
      if (current.sidebar.type === "node")
        dispatch({ type: "NODE_FIELD", field, value });
      else if (current.sidebar.type === "edge" && field !== "notes")
        dispatch({ type: "EDGE_FIELD", field, value });
    };
    title.addEventListener("input", () => edit("title", title.value));
    description.addEventListener("input", () =>
      edit("description", description.value),
    );
    notes.addEventListener("input", () => edit("notes", notes.value));
    this.syncCurrent = (s: State) => {
      current = s;
    };

    this.b
      .ref(saveRef)
      .addEventListener("click", () => dispatch({ type: "SAVE" }));
    this.b
      .ref(deleteRef)
      .addEventListener("click", () => dispatch({ type: "DELETE" }));
    this.b
      .ref(closeRef)
      .addEventListener("click", () => dispatch({ type: "CLOSE" }));

    this.b.bindVisible(emptyRef, (s) => s.nodes.length === 0);
    this.b.bindVisible(closedRef, (s) => s.sidebar.type === "closed");
    this.b.bindVisible(openRef, (s) => s.sidebar.type !== "closed");
    this.b.bindVisible(notesRowRef, (s) => s.sidebar.type === "node");
    this.b.bindVisible(levelRowRef, (s) => s.sidebar.type === "node");
    this.b.bindText(kindRef, (s) =>
      s.sidebar.type === "closed" ? "" : `${s.sidebar.type} ${s.sidebar.id}`,
    );
    this.b.bindValue(titleRef, (s) =>
      s.sidebar.type === "closed" ? "" : s.sidebar.draft.title,
    );
    this.b.bindValue(descriptionRef, (s) =>
      s.sidebar.type === "closed" ? "" : s.sidebar.draft.description,
    );
    this.b.bindValue(notesRef, (s) =>
      s.sidebar.type === "node" ? s.sidebar.draft.notes : "",
    );
    this.b.bindValue(levelRef, (s) =>
      s.sidebar.type === "node" ? String(s.sidebar.draft.level) : "1",
    );
    this.b.bindText(errorRef, (s) =>
      s.sidebar.type === "closed" ? "" : (s.sidebar.error ?? ""),
    );
    this.b.bindVisible(errorRef, (s) =>
      s.sidebar.type === "closed" ? false : s.sidebar.error !== null,
    );
  }

  private syncCurrent: (s: State) => void;

  sync(state: State): void {
    this.syncCurrent(state);
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

function selectedId(s: State): string | null {
  return s.sidebar.type === "closed" ? null : s.sidebar.id;
}

import { expect, it } from "vitest";
import { KnowledgeGraph, LEVELS } from "./graph.ts";
import { LEARNING_SYSTEM, seedTurn } from "./prompt.ts";
import type { Anchor, ThreadId } from "./selection.ts";

const messages = [
  { type: "text" as const, role: "user" as const, text: "build a parser" },
  {
    type: "text" as const,
    role: "assistant" as const,
    text: "I used a recursive descent approach.",
  },
  { type: "text" as const, role: "user" as const, text: "thanks" },
] as const;

const at = (
  startMsg: number,
  start: number,
  endMsg: number,
  end: number,
): Anchor => ({
  thread: "root" as ThreadId,
  start: { msg: startMsg, offset: start },
  end: { msg: endMsg, offset: end },
});

it("quotes the selection verbatim", () => {
  const seed = seedTurn(undefined, messages, at(1, 9, 1, 26), {
    type: "explain",
  });
  expect(seed).toContain('The user then selected: "recursive descent"');
});

it("quotes a selection spanning two messages", () => {
  const seed = seedTurn(undefined, messages, at(0, 6, 1, 6), { type: "quiz" });
  expect(seed).toContain('selected: "a parser\n\nI used"');
});

it("truncates the transcript after the message containing the selection end", () => {
  const seed = seedTurn(undefined, messages, at(1, 0, 1, 5), {
    type: "explain",
  });
  expect(seed).toContain("build a parser");
  expect(seed).not.toContain("thanks");
});

it("distinguishes the three actions and carries a query through", () => {
  const anchor = at(1, 9, 1, 26);
  const explain = seedTurn(undefined, messages, anchor, { type: "explain" });
  const quiz = seedTurn(undefined, messages, anchor, { type: "quiz" });
  const query = seedTurn(undefined, messages, anchor, {
    type: "query",
    text: "why not a parser generator?",
  });
  expect(new Set([explain, quiz, query]).size).toBe(3);
  expect(query).toContain("why not a parser generator?");
});

it("composes flat at depth, oldest section first", () => {
  const root = seedTurn(undefined, messages, at(1, 9, 1, 26), {
    type: "explain",
  });
  const level1 = [
    {
      type: "text" as const,
      role: "assistant" as const,
      text: "It parses top-down.",
    },
  ] as const;
  const depth2 = seedTurn(root, level1, at(0, 10, 0, 18), { type: "quiz" });

  expect(depth2).toBe(
    [
      "User: build a parser",
      "",
      "Assistant: I used a recursive descent approach.",
      "",
      'The user then selected: "recursive descent"',
      "They said they don't understand this. Explain what it means and why it is there.",
      "",
      "Assistant: It parses top-down.",
      "",
      'The user then selected: "top-down"',
      "They asked to be quizzed on this. Ask one question that checks whether they understand it, and wait for their answer.",
    ].join("\n"),
  );
  expect(depth2.startsWith(root)).toBe(true);
  expect(depth2.split("build a parser")).toHaveLength(2);

  const level2 = [
    {
      type: "text" as const,
      role: "assistant" as const,
      text: "Question: what is a token?",
    },
  ] as const;
  const depth3 = seedTurn(depth2, level2, at(0, 0, 0, 8), {
    type: "query",
    text: "what?",
  });
  expect(depth3.startsWith(depth2)).toBe(true);
  expect(depth3.split("build a parser")).toHaveLength(2);
  expect(depth3.split("It parses top-down")).toHaveLength(2);
});

it("names the get tool and the scale in the learning system prompt", () => {
  expect(LEARNING_SYSTEM).toContain("`get`");
  for (const label of LEVELS) expect(LEARNING_SYSTEM).toContain(label);
});

it("renders the graph into a top-level seed, and only there", () => {
  const graph = new KnowledgeGraph();
  graph.putNode({
    title: "recursive descent",
    description: "top-down parsing",
    notes: "asked about it",
    level: 2,
  });
  const rendered = graph.render();
  const top = seedTurn(
    undefined,
    messages,
    at(1, 9, 1, 26),
    { type: "explain" },
    rendered,
  );
  expect(top).toContain(rendered);
  const deeper = seedTurn(
    top,
    messages,
    at(1, 9, 1, 26),
    { type: "explain" },
    rendered,
  );
  expect(deeper.split(rendered)).toHaveLength(2);
});

import type { ClientMessage, ServerFrame } from "@edulab/iso/protocol.ts";
import { expect, type Page, test } from "@playwright/test";

/** Answers every request with a one-word reply: this spec is about the graph
 * tab, and the transcript only has to exist. */
async function backend(page: Page) {
  await page.routeWebSocket("**/api/socket", (ws) => {
    ws.onMessage((raw) => {
      const message = JSON.parse(String(raw)) as ClientMessage;
      const send = (frame: ServerFrame) => ws.send(JSON.stringify(frame));
      send({
        type: "event",
        requestId: message.requestId,
        event: {
          type: "content_block_start",
          index: 0,
          content_block: { type: "text", text: "ok", citations: null },
        },
      });
      send({
        type: "event",
        requestId: message.requestId,
        event: { type: "content_block_stop", index: 0 },
      });
      send({ type: "done", requestId: message.requestId });
    });
  });
}

/** Nothing writes to the graph until the extraction thread of the next stage,
 * so the spec seeds it through the handle the prototype exposes. */
async function seed(page: Page) {
  await page.evaluate(() => {
    const graph = (
      window as unknown as {
        __graph: {
          putNode(n: {
            title: string;
            description: string;
            notes: string;
            level: number;
          }): unknown;
          putEdge(e: {
            from: string;
            to: string;
            title: string;
            description: string;
          }): unknown;
        };
      }
    ).__graph;
    graph.putNode({
      title: "closures",
      description: "a function plus its environment",
      notes: "asked about capture twice",
      level: 2,
    });
    graph.putNode({
      title: "scope",
      description: "where a binding is visible",
      notes: "",
      level: 3,
    });
    graph.putEdge({
      from: "n0",
      to: "n1",
      title: "builds on",
      description: "a closure captures a scope",
    });
  });
}

function graphTab(page: Page) {
  return page.getByRole("button", { name: "Knowledge graph" });
}

function threadsTab(page: Page) {
  return page.getByRole("button", { name: "Threads", exact: true });
}

function nodes(page: Page) {
  return page.locator("[data-node]");
}

async function open(page: Page) {
  await backend(page);
  await page.goto("/");
  await seed(page);
  await graphTab(page).click();
}

test("switching tabs leaves the transcript and the graph intact", async ({
  page,
}) => {
  await backend(page);
  await page.goto("/");
  await page.getByRole("textbox").fill("hello");
  await page.getByRole("textbox").press("Enter");
  await expect(page.locator("ul").first().locator("li")).toHaveCount(2);
  await seed(page);

  await graphTab(page).click();
  await expect(nodes(page)).toHaveCount(2);
  await expect(page.locator("[data-edge]")).toHaveCount(1);

  await threadsTab(page).click();
  await expect(page.locator("ul").first().locator("li")).toHaveCount(2);

  await graphTab(page).click();
  await expect(nodes(page)).toHaveCount(2);
});

test("clicking a node fills the sidebar and a retitle keeps its edges", async ({
  page,
}) => {
  await open(page);
  await nodes(page).filter({ hasText: "closures" }).click();

  await expect(page.locator("[data-graph-title]")).toHaveValue("closures");
  await expect(page.locator("[data-graph-description]")).toHaveValue(
    "a function plus its environment",
  );
  await expect(page.locator("[data-graph-notes]")).toHaveValue(
    "asked about capture twice",
  );
  await expect(page.locator("[data-graph-level]")).toHaveValue("2");

  await page.locator("[data-graph-title]").fill("lexical closures");
  await page.getByRole("button", { name: "Save" }).click();

  await expect(nodes(page)).toHaveText(["lexical closures", "scope"]);
  await expect(page.locator("[data-edge]")).toHaveCount(1);
  await expect(page.locator("[data-edge-label]")).toHaveText("builds on");
});

test("a duplicate title is rejected without losing the draft", async ({
  page,
}) => {
  await open(page);
  await nodes(page).filter({ hasText: "closures" }).click();
  await page.locator("[data-graph-title]").fill("scope");
  await page.getByRole("button", { name: "Save" }).click();

  await expect(page.locator("[data-graph-error]")).toHaveText(/already used/);
  await expect(page.locator("[data-graph-title]")).toHaveValue("scope");
  await expect(nodes(page)).toHaveText(["closures", "scope"]);
});

test("deleting a node takes its edges with it", async ({ page }) => {
  await open(page);
  await nodes(page).filter({ hasText: "closures" }).click();
  await page.getByRole("button", { name: "Delete" }).click();

  await expect(nodes(page)).toHaveText(["scope"]);
  await expect(page.locator("[data-edge]")).toHaveCount(0);
  await expect(page.getByText("Click a node or an edge")).toBeVisible();
});

test("an edge is selectable and editable", async ({ page }) => {
  await open(page);
  await page.locator("[data-edge-label]").click();

  await expect(page.locator("[data-graph-title]")).toHaveValue("builds on");
  await expect(page.locator("[data-graph-notes]")).toBeHidden();

  await page.locator("[data-graph-title]").fill("requires");
  await page.getByRole("button", { name: "Save" }).click();
  await expect(page.locator("[data-edge-label]")).toHaveText("requires");
});

