function startBlock(block: Anthropic.ContentBlock): PendingBlock | undefined {
  switch (block.type) {
    case "text":
      return { type: "text", text: block.text };
    case "tool_use":
      return {
        type: "tool_use",
        id: block.id,
        name: block.name,
        inputJson: "",
        input: undefined,
